"use strict";(globalThis.webpackChunktechnical_writing_portfolio=globalThis.webpackChunktechnical_writing_portfolio||[]).push([[5479],{7119(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>r,default:()=>h,frontMatter:()=>a,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"atlas-copco/flow-drill-fastening","title":"Henrob tape feed riveting documentation","description":"When I started working on the Henrob tape feed riveting documentation at Atlas Copco, I knew I was dealing with something special. This wasn\'t just another joining technology - it was a servo-driven system capable of setting rivets in just 1.2 seconds for high-volume automotive production.","source":"@site/docs/atlas-copco/flow-drill-fastening.md","sourceDirName":"atlas-copco","slug":"/atlas-copco/flow-drill-fastening","permalink":"/technical-writing-portfolio/docs/atlas-copco/flow-drill-fastening","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3},"sidebar":"tutorialSidebar","previous":{"title":"Self-pierce riveting documentation","permalink":"/technical-writing-portfolio/docs/atlas-copco/self-pierce-riveting"},"next":{"title":"Henrob blow feed riveting documentation","permalink":"/technical-writing-portfolio/docs/atlas-copco/industrial-dispensing"}}');var o=n(4848),s=n(8453);const a={sidebar_position:3},r="Henrob tape feed riveting documentation",c={},d=[{value:"Writing process and approach",id:"writing-process-and-approach",level:2},{value:"Connecting technical depth with practical needs",id:"connecting-technical-depth-with-practical-needs",level:2},{value:"Industry-specific writing challenges",id:"industry-specific-writing-challenges",level:2},{value:"Process optimization through documentation",id:"process-optimization-through-documentation",level:2},{value:"Integration with existing documentation systems",id:"integration-with-existing-documentation-systems",level:2},{value:"Results and impact",id:"results-and-impact",level:2}];function l(e){const t={h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"henrob-tape-feed-riveting-documentation",children:"Henrob tape feed riveting documentation"})}),"\n",(0,o.jsx)(t.p,{children:"When I started working on the Henrob tape feed riveting documentation at Atlas Copco, I knew I was dealing with something special. This wasn't just another joining technology - it was a servo-driven system capable of setting rivets in just 1.2 seconds for high-volume automotive production."}),"\n",(0,o.jsx)(t.h2,{id:"writing-process-and-approach",children:"Writing process and approach"}),"\n",(0,o.jsx)(t.p,{children:"I began by spending time on the factory floor watching these machines work. The tape feed system was fascinating - rivets loaded from continuous tape, positioned with servo precision, and set at incredible speeds. But explaining that in a way that made sense to engineers, technicians, and production managers required a completely different approach."}),"\n",(0,o.jsx)(t.p,{children:"The challenge was translating the complex mechanics of servo technology and rivet formation into something actionable. I worked closely with the engineering team to understand not just what the system did, but why design decisions were made and how different settings affected outcomes."}),"\n",(0,o.jsx)(t.h2,{id:"connecting-technical-depth-with-practical-needs",children:"Connecting technical depth with practical needs"}),"\n",(0,o.jsx)(t.p,{children:"Much like the server-sent events documentation I created at Ably, this project required bridging the gap between complex technical concepts and real-world implementation. The tape feed system had dozens of parameters that could be adjusted, but operators needed to know which ones mattered for their specific applications."}),"\n",(0,o.jsx)(t.p,{children:"I developed a layered approach to the documentation. Quick reference guides for day-to-day operation, deeper technical sections for setup and troubleshooting, and comprehensive theory sections for engineers designing production systems. This mirrors how I structured the troubleshooting guides at Ably - different users needed different levels of detail at different times."}),"\n",(0,o.jsx)(t.h2,{id:"industry-specific-writing-challenges",children:"Industry-specific writing challenges"}),"\n",(0,o.jsx)(t.p,{children:"Automotive manufacturing documentation is different from software documentation in critical ways. Safety is paramount - a mistake doesn't just cause a system error, it can shut down an entire production line or cause safety issues. Every procedure had to include proper lockout/tagout protocols and safety warnings."}),"\n",(0,o.jsx)(t.p,{children:"I also had to consider the global nature of Atlas Copco's customer base. These systems were shipping to factories in Germany, Mexico, China, and dozens of other countries. The documentation needed to work across different languages, safety standards, and manufacturing cultures."}),"\n",(0,o.jsx)(t.h2,{id:"process-optimization-through-documentation",children:"Process optimization through documentation"}),"\n",(0,o.jsx)(t.p,{children:"The most rewarding part of this project was seeing how good documentation could actually improve the technology itself. As I worked through different use cases and edge conditions, I discovered scenarios the engineering team hadn't fully considered. This feedback loop between documentation and product development made both better."}),"\n",(0,o.jsx)(t.p,{children:"I documented not just the current capabilities, but also pushed the team to clarify limitations and specify operating boundaries. This prevented customer applications outside the system's design parameters and reduced support calls."}),"\n",(0,o.jsx)(t.h2,{id:"integration-with-existing-documentation-systems",children:"Integration with existing documentation systems"}),"\n",(0,o.jsx)(t.p,{children:"This work connected directly to the broader self-pierce riveting documentation I was developing. Both systems served the automotive lightweighting market, but for different applications and production volumes. I made sure the documentation clearly explained when to use tape feed versus other joining methods."}),"\n",(0,o.jsx)(t.p,{children:"Similar to how I restructured information architecture at Ably, I organized this documentation around user workflows rather than technical features. Production engineers didn't care about servo motor specifications - they cared about cycle times, quality metrics, and changeover procedures."}),"\n",(0,o.jsx)(t.h2,{id:"results-and-impact",children:"Results and impact"}),"\n",(0,o.jsx)(t.p,{children:"The tape feed documentation became a model for other Atlas Copco product lines. The modular structure made it easy to adapt for different markets and applications. More importantly, it reduced the learning curve for new installations and improved troubleshooting efficiency when production issues arose."}),"\n",(0,o.jsx)(t.p,{children:"This project taught me that industrial documentation requires the same user-centered thinking as software documentation, but with much higher stakes. The principles I learned here - clarity, safety-first thinking, and global accessibility - influenced how I approached every subsequent technical writing project."})]})}function h(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},8453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var i=n(6540);const o={},s=i.createContext(o);function a(e){const t=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),i.createElement(s.Provider,{value:t},e.children)}}}]);